"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[23273],{70852(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>u,default:()=>m,frontMatter:()=>o,metadata:()=>r,toc:()=>c});var i=t.cw((e,n)=>{const i=t.p+"assets/images/cours-p10-1-84246fb1e9f134906129640a435be131.png";t.d(n,["A",0,i])}),s=t.cw((e,n)=>{const i=t.p+"assets/images/cours-p12-1-8fb6d7544c94c59a0fa014a09ad901f0.png";t.d(n,["A",0,i])});const r=JSON.parse('{"id":"scolarite/cpbx/s3/chimie/limites-theories-classiques","title":"Les limites des th\xe9ories classiques","description":"Structure de l\'atome, aspect corpusculaire de la lumi\xe8re (corps noir, effet photo\xe9lectrique), quantification du spectre de l\'hydrog\xe8ne et mod\xe8le de Bohr, aspect ondulatoire de la mati\xe8re (de Broglie, interf\xe9rences \xe9lectroniques) et principe d\'incertitude de Heisenberg.","source":"@site/docs/scolarite/cpbx/s3/chimie/limites-theories-classiques.md","sourceDirName":"scolarite/cpbx/s3/chimie","slug":"/scolarite/cpbx/s3/chimie/limites-theories-classiques","permalink":"/docs/scolarite/cpbx/s3/chimie/limites-theories-classiques","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1792955287000,"sidebarPosition":2,"frontMatter":{"title":"Les limites des th\xe9ories classiques","description":"Structure de l\'atome, aspect corpusculaire de la lumi\xe8re (corps noir, effet photo\xe9lectrique), quantification du spectre de l\'hydrog\xe8ne et mod\xe8le de Bohr, aspect ondulatoire de la mati\xe8re (de Broglie, interf\xe9rences \xe9lectroniques) et principe d\'incertitude de Heisenberg.","sidebar_position":2},"sidebar":"tutorialSidebar","previous":{"title":"Rappels de m\xe9canique et d\'\xe9lectromagn\xe9tisme classiques","permalink":"/docs/scolarite/cpbx/s3/chimie/rappels-classiques"},"next":{"title":"Les postulats de la m\xe9canique quantique","permalink":"/docs/scolarite/cpbx/s3/chimie/postulats-mecanique-quantique"}}');var a=t(74848),l=t(28453);const o={title:"Les limites des th\xe9ories classiques",description:"Structure de l'atome, aspect corpusculaire de la lumi\xe8re (corps noir, effet photo\xe9lectrique), quantification du spectre de l'hydrog\xe8ne et mod\xe8le de Bohr, aspect ondulatoire de la mati\xe8re (de Broglie, interf\xe9rences \xe9lectroniques) et principe d'incertitude de Heisenberg.",sidebar_position:2},u=void 0,d={},c=[{value:"Structure de l&#39;atome",id:"structure-de-latome",level:2},{value:"Aspect corpusculaire de la lumi\xe8re",id:"aspect-corpusculaire-de-la-lumi\xe8re",level:2},{value:"Quantification du spectre de l&#39;hydrog\xe8ne",id:"quantification-du-spectre-de-lhydrog\xe8ne",level:2},{value:"Aspect ondulatoire de la mati\xe8re",id:"aspect-ondulatoire-de-la-mati\xe8re",level:2}];function p(e){const n={em:"em",h2:"h2",img:"img",li:"li",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,l.R)(),...e.components},{Katex:t}=n;return t||function(e,n){throw new Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Katex",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.p,{children:"\xc0 la fin du 19e si\xe8cle, les deux piliers de la physique que constituent la m\xe9canique et l'\xe9lectromagn\xe9tisme semblaient capables de rationaliser l'ensemble des lois de la nature. Cependant, l'examen critique des ph\xe9nom\xe8nes li\xe9s \xe0 l'interaction entre la mati\xe8re et un rayonnement \xe9lectromagn\xe9tique fit appara\xeetre la n\xe9cessit\xe9 de remettre en cause cet \xe9difice. L'analyse de plusieurs exp\xe9riences (rayonnement du corps noir, effet photo\xe9lectrique, exp\xe9riences de diffraction d'\xe9lectrons ou de neutrons...) a mis en \xe9vidence le fait que les particules \xe9l\xe9mentaires ne se conforment pas aux lois de la m\xe9canique classique, et se manifestent parfois selon des lois similaires \xe0 celles qui r\xe9gissent les ondes. \xc0 l'oppos\xe9, les ondes lumineuses se manifestent aussi sous forme corpusculaire. Ces ph\xe9nom\xe8nes sont \xe0 l'origine de la r\xe9volution de la physique au d\xe9but du si\xe8cle, et sont d\xe9crits par les relations de dualit\xe9 onde-corpuscule."}),"\n",(0,a.jsx)(n.h2,{id:"structure-de-latome",children:"Structure de l'atome"}),"\n",(0,a.jsxs)(n.p,{children:["En 1897, le physicien anglais Thomson observe que lorsqu'on \xe9tablit une diff\xe9rence de potentiel entre deux \xe9lectrodes plac\xe9es dans un tube en verre \xe0 l'int\xe9rieur duquel la pression est tr\xe8s faible, un spot lumineux (appel\xe9 rayon cathodique) appara\xeet sur le verre derri\xe8re l'\xe9lectrode positive. Une \xe9tude d\xe9taill\xe9e des d\xe9viations subies par le rayon cathodique sous l'effet de champs \xe9lectriques et magn\xe9tiques montre qu'il s'agit d'un courant de particules ind\xe9pendantes du mat\xe9riau et charg\xe9es n\xe9gativement, les \xe9lectrons. Quelques ann\xe9es plus tard, Millikan d\xe9termine la valeur de la charge de l'\xe9lectron en \xe9tudiant les mouvements de gouttelettes d'huile \xe9lectris\xe9es entre les plaques d'un condensateur horizontal. Cette valeur, not\xe9e conventionnellement ",(0,a.jsx)(t,{tex:"e"}),", constitue la plus petite charge \xe9lectrique que puisse porter une particule. Toute charge \xe9lectrique ne peut \xeatre, en valeur absolue, qu'un multiple entier de celle de l'\xe9lectron :"]}),"\n",(0,a.jsx)(t,{tex:"e = 1{,}602177 \\cdot 10^{-19}\\ \\text{C}",display:!0}),"\n",(0,a.jsx)(n.p,{children:"Autre conclusion importante des observations de Thomson : les \xe9lectrons portant une charge n\xe9gative et \xe9tant \xe9mis par des m\xe9taux initialement neutres, une source de charges positives doit exister dans les m\xe9taux. En 1911, Rutherford montre exp\xe9rimentalement que presque toute la masse et toute la charge positive d'un atome sont localis\xe9es en son centre, qu'il appelle le noyau. Il propose alors une structure de l'atome de type plan\xe9taire, dans laquelle les \xe9lectrons charg\xe9s n\xe9gativement orbitent autour du noyau. Dans ce mod\xe8le, la coh\xe9sion de l'\xe9difice atomique r\xe9sulte de la force de Coulomb, jouant pour l'atome le r\xf4le de la force de gravitation dans un syst\xe8me plan\xe9taire."}),"\n",(0,a.jsxs)(n.p,{children:["Ce mod\xe8le plan\xe9taire souffre cependant d'une incoh\xe9rence li\xe9e aux lois de l'\xe9lectromagn\xe9tisme. En effet, les particules charg\xe9es en mouvement acc\xe9l\xe9r\xe9 sont susceptibles d'\xe9mettre un rayonnement lumineux. Le mouvement de rotation d'un \xe9lectron autour du noyau fait que le champ \xe9lectrique cr\xe9\xe9 par le dip\xf4le que constituent les deux particules charg\xe9es varie au cours du temps : ce dip\xf4le \xe9lectron-proton change d'orientation au fur et \xe0 mesure que l'\xe9lectron tourne autour du proton. L'atome cr\xe9e donc un champ \xe9lectrique oscillant, c'est-\xe0-dire une onde \xe9lectromagn\xe9tique. Il perd donc contin\xfbment de l'\xe9nergie sous forme \xe9lectromagn\xe9tique. La conservation de l'\xe9nergie totale implique que l'\xe9nergie rayonn\xe9e correspond \xe0 une perte d'\xe9nergie m\xe9canique de l'\xe9lectron. Celui-ci doit perdre de \"l'altitude\". Le terme in\xe9luctable de sa trajectoire est la collision avec le noyau, avec pour l'atome une dur\xe9e de vie estim\xe9e de l'ordre de ",(0,a.jsx)(t,{tex:"10^{-8}"})," seconde. La r\xe9alit\xe9 est \xe9videmment tout autre ; les atomes sont stables et n'\xe9mettent pas spontan\xe9ment de lumi\xe8re. La physique classique est donc incapable de rendre compte de l'existence des atomes et donc des mol\xe9cules. L'existence de deux th\xe9ories"]}),"\n",(0,a.jsx)(n.h2,{id:"aspect-corpusculaire-de-la-lumi\xe8re",children:"Aspect corpusculaire de la lumi\xe8re"}),"\n",(0,a.jsx)(n.p,{children:"La nature de la lumi\xe8re est un probl\xe8me qui a suscit\xe9 un grand nombre de controverses scientifiques pendant plusieurs si\xe8cles. En 1704, Newton sugg\xe8re qu'un faisceau lumineux pourrait \xeatre constitu\xe9 de corpuscules tr\xe8s fins. Cette hypoth\xe8se est en accord avec les lois de l'optique g\xe9om\xe9trique : la conservation de la quantit\xe9 de mouvement explique la propagation rectiligne du flux lumineux, et le ph\xe9nom\xe8ne de r\xe9flexion provient des collisions \xe9lastiques entre les corpuscules et le miroir, et appara\xeet donc comme une cons\xe9quence directe de la conservation de l'\xe9nergie et de la quantit\xe9 de mouvement. Contemporain de Newton, le physicien n\xe9erlandais Huygens \xe9met l'hypoth\xe8se que la lumi\xe8re est un ph\xe9nom\xe8ne ondulatoire. Cette hypoth\xe8se offre le moyen de d\xe9crire parfaitement les rayons lumineux, mais se heurte \xe0 un probl\xe8me insurmontable : \xe0 cette \xe9poque, tous les ph\xe9nom\xe8nes ondulatoires connus (ondes aquatiques, ondes sonores...) n\xe9cessitent un milieu \xe0 travers lequel se propager. Dans ce cas, comment expliquer que la lumi\xe8re traverse le vide ? Pour contourner cette difficult\xe9, on postula l'existence de l'\xe9ther, milieu dans lequel toute onde lumineuse peut se propager. Pendant un si\xe8cle, les descriptions ondulatoire et corpusculaire de la lumi\xe8re coexistent. Il faut attendre les travaux de Young en 1801, et en particulier l'observation des ph\xe9nom\xe8nes de diffraction et d'interf\xe9rences, pour que soit abandonn\xe9e la description corpusculaire de la lumi\xe8re. Si un faisceau lumineux rencontre une fente tr\xe8s \xe9troite perc\xe9e dans un \xe9cran opaque, la lumi\xe8re qui traverse la fente se propage dans toutes les directions, de mani\xe8re analogue aux ondes aquatiques : c'est la diffraction. Si deux faisceaux diffract\xe9s qui se recouvrent sont projet\xe9s sur un \xe9cran, il appara\xeet sur l'\xe9cran une alternance de bandes lumineuses et de bandes sombres, appel\xe9e figure d'interf\xe9rences. La th\xe9orie corpusculaire ne permet pas d'expliquer ces deux ph\xe9nom\xe8nes : ils prouvent le caract\xe8re ondulatoire de la lumi\xe8re. En 1862, Maxwell montre que l'onde lumineuse est de nature \xe9lectromagn\xe9tique et propose une s\xe9rie d'\xe9quations d\xe9crivant sa propagation. \xc0 la fin du 19e si\xe8cle, il semble donc d\xe9finitivement acquis que la lumi\xe8re est une onde. Mais une s\xe9rie d'exp\xe9riences men\xe9es au d\xe9but du 20e si\xe8cle viennent remettre en question cette description, et relancer la controverse."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Le rayonnement du corps noir."})," Un corps noir est un objet non r\xe9fl\xe9chissant qui \xe9met de la lumi\xe8re lorsqu'il est chauff\xe9. Lorsqu'un corps noir est port\xe9 \xe0 haute temp\xe9rature, il \xe9met un rayonnement appel\xe9 rayonnement thermique, dont le taux d'\xe9mission ",(0,a.jsx)(t,{tex:"R"})," est proportionnel \xe0 la puissance 4 de la temp\xe9rature (loi de Stefan, 1879). Si un rayonnement thermique \xe0 taux constant est envoy\xe9 sur un corps noir, la temp\xe9rature de ce dernier s'\xe9l\xe8ve ; il \xe9met alors \xe0 son tour un rayonnement, dont le taux d'\xe9mission devient de plus en plus intense \xe0 mesure que la temp\xe9rature augmente. La temp\xe9rature se stabilise lorsque le taux d'\xe9mission est \xe9gal au taux d'absorption. Le syst\xe8me est alors dans un \xe9tat d'\xe9quilibre thermodynamique."]}),"\n",(0,a.jsx)(n.p,{children:"\xc0 la fin du 19e si\xe8cle, Rayleigh et Jeans proposent une loi de distribution spectrale du rayonnement \xe0 l'\xe9quilibre thermodynamique, \xe0 partir de la th\xe9orie cin\xe9tique de la mati\xe8re et des statistiques de Boltzmann. Dans ce mod\xe8le, les ions oscillent avec un ensemble continu de fr\xe9quences autour de leur position moyenne ; ces oscillations sont responsables de l'\xe9mission du rayonnement. Le spectre du corps noir est alors donn\xe9 par :"}),"\n",(0,a.jsx)(t,{tex:"R(\\lambda) = \\frac{8\\pi k}{\\lambda^4} T",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["o\xf9 ",(0,a.jsx)(t,{tex:"k"})," est la constante de Boltzmann."]}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.img,{alt:"Spectre du corps noir \xe0 1 000, 1 500, 1 750 et 2 000 K compar\xe9 \xe0 la loi de Rayleigh-Jeans",src:i().A+"",width:"521",height:"451"})}),"\n",(0,a.jsx)(n.p,{children:"Comme le montre la figure, la loi de Rayleigh-Jeans ne permet de rendre compte de l'\xe9mission du corps noir qu'aux grandes longueurs d'onde (faibles fr\xe9quences). Pour des longueurs d'onde inf\xe9rieures, elle fait appara\xeetre une divergence dramatique par rapport \xe0 la distribution exp\xe9rimentale. Cette divergence est appel\xe9e \"catastrophe ultra-violette\", car la discordance devient particuli\xe8rement marqu\xe9e pour les longueurs d'onde correspondant \xe0 l'ultra-violet."}),"\n",(0,a.jsxs)(n.p,{children:["En 1900, Max Planck propose une solution permettant de r\xe9soudre le probl\xe8me pos\xe9 par la catastrophe UV et de d\xe9crire compl\xe8tement l'ensemble du spectre du corps noir. Le point central de la solution de Planck est que les ions oscillants ne se comportent pas comme des oscillateurs classiques, et n'\xe9mettent pas une \xe9nergie variant de fa\xe7on continue. Ils ne peuvent \xe9mettre qu'une \xe9nergie \xe9gale \xe0 un multiple entier d'une quantit\xe9 de base ",(0,a.jsx)(t,{tex:"h\\nu"})," (le quantum d'\xe9nergie), o\xf9 ",(0,a.jsx)(t,{tex:"\\nu"})," est la fr\xe9quence de l'oscillateur. La constante ",(0,a.jsx)(t,{tex:"h"})," fut propos\xe9e comme nouvelle constante universelle. Sa dimension est celle d'une action (une \xe9nergie fois un temps). Les d\xe9terminations exp\xe9rimentales ult\xe9rieures de ",(0,a.jsx)(t,{tex:"h"})," conduisent \xe0 la valeur :"]}),"\n",(0,a.jsx)(t,{tex:"h = 6{,}6253 \\cdot 10^{-34}\\ \\text{J.s}",display:!0}),"\n",(0,a.jsx)(n.p,{children:"L'\xe9change d'\xe9nergie entre le rayonnement et la cavit\xe9 est donc discontinu, ou quantifi\xe9. L'introduction de la condition de quantification dans la statistique de Boltzmann conduit \xe0 une modification de la loi de distribution spectrale qui reproduit parfaitement la loi exp\xe9rimentale :"}),"\n",(0,a.jsx)(t,{tex:"R(\\lambda) = \\frac{8\\pi hc}{\\lambda^5} \\frac{1}{\\exp(hc/k\\lambda T) - 1}",display:!0}),"\n",(0,a.jsx)(n.p,{children:"En contradiction avec les lois classiques de la thermodynamique et de l'\xe9lectromagn\xe9tisme, la quantification de l'\xe9change d'\xe9nergie entre mati\xe8re et rayonnement appara\xeet \xe0 l'\xe9poque comme une r\xe9volution. Planck lui-m\xeame \xe9met des doutes quant \xe0 la validit\xe9 de son postulat. Mais en 1905, Einstein montre qu'une g\xe9n\xe9ralisation du postulat de Planck permet de comprendre un autre ph\xe9nom\xe8ne que la physique classique ne peut expliquer : l'effet photo\xe9lectrique."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"L'effet photo\xe9lectrique."})," Sous irradiation ultraviolette, un m\xe9tal \xe9met spontan\xe9ment des \xe9lectrons. La premi\xe8re observation exp\xe9rimentale de ce ph\xe9nom\xe8ne, appel\xe9 effet photo\xe9lectrique, a \xe9t\xe9 faite par Becquerel en 1839. Les exp\xe9riences de Lenard en 1900 en donnent les caract\xe9ristiques principales :"]}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:["pour chaque type de m\xe9tal, il existe une fr\xe9quence seuil ",(0,a.jsx)(t,{tex:"\\nu_0"})," en de\xe7\xe0 de laquelle on n'observe pas d'\xe9mission de \"photo\xe9lectrons\" ;"]}),"\n",(0,a.jsx)(n.li,{children:"le nombre d'\xe9lectrons \xe9mis par le m\xe9tal d\xe9pend de l'intensit\xe9 lumineuse, mais leur vitesse ne d\xe9pend que de la fr\xe9quence du rayonnement UV ;"}),"\n",(0,a.jsx)(n.li,{children:"l'\xe9mission est un ph\xe9nom\xe8ne instantan\xe9, m\xeame pour de tr\xe8s faibles intensit\xe9s."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Ces faits sont compl\xe8tement incompr\xe9hensibles avec l'image classique d'un \xe9change continu d'\xe9nergie entre la mati\xe8re et le rayonnement."}),"\n",(0,a.jsxs)(n.p,{children:["L'interpr\xe9tation des lois exp\xe9rimentales est due \xe0 Albert Einstein en 1905. Sur la base des travaux de Planck, Einstein suppose qu'un rayonnement \xe9lectromagn\xe9tique est compos\xe9 de corpuscules de masse au repos nulle, baptis\xe9s photons par la suite. La relation liant l'\xe9nergie ",(0,a.jsx)(t,{tex:"E"})," port\xe9e par les photons et la fr\xe9quence ",(0,a.jsx)(t,{tex:"\\nu"})," du rayonnement lumineux est appel\xe9e relation de Planck-Einstein :"]}),"\n",(0,a.jsx)(t,{tex:"E = h\\nu = hc/\\lambda",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["Pour extraire un \xe9lectron d'un m\xe9tal, il faut fournir une \xe9nergie minimale ",(0,a.jsx)(t,{tex:"W"}),". Lorsqu'un photon est absorb\xe9 sur une surface m\xe9tallique, il c\xe8de \xe0 l'\xe9lectron un quantum d'\xe9nergie ",(0,a.jsx)(t,{tex:"h\\nu"}),". Si la fr\xe9quence ",(0,a.jsx)(t,{tex:"\\nu"})," est suffisamment \xe9lev\xe9e, l'\xe9lectron est arrach\xe9 du m\xe9tal. L'exc\xe9dent d'\xe9nergie permet \xe0 l'\xe9lectron d'acqu\xe9rir une certaine \xe9nergie cin\xe9tique. Ceci se traduit par l'\xe9quation :"]}),"\n",(0,a.jsx)(t,{tex:"h\\nu = \\frac{1}{2} m v^2 + W",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["o\xf9 ",(0,a.jsx)(t,{tex:"v"})," est la vitesse du photo\xe9lectron. L'existence d'une valeur limite de la fr\xe9quence en dessous de laquelle l'effet photo\xe9lectrique n'est plus observ\xe9 se comprend alors facilement : si l'on diminue la fr\xe9quence du rayonnement incident, l'\xe9nergie cin\xe9tique du photo\xe9lectron diminue jusqu'\xe0 une fr\xe9quence seuil ",(0,a.jsx)(t,{tex:"\\nu_0"})," correspondant \xe0 une \xe9nergie cin\xe9tique nulle. Le photon poss\xe8de alors juste assez d'\xe9nergie pour arracher l'\xe9lectron du m\xe9tal :"]}),"\n",(0,a.jsx)(t,{tex:"h\\nu_0 = W",display:!0}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.img,{alt:"Appareil de Lenard pour \xe9tudier l&#39;\xe9mission photo\xe9lectrique d&#39;une cathode C \xe9clair\xe9e par une source lumineuse",src:s().A+"",width:"572",height:"253"})}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsxs)(n.em,{children:["Figure 1 \u2013 Appareil de Lenard pour \xe9tudier l'\xe9mission photo\xe9lectrique d'une cathode ",(0,a.jsx)(t,{tex:"C"})," \xe9clair\xe9e par une source lumineuse."]})}),"\n",(0,a.jsxs)(n.p,{children:["L'\xe9nergie d'ionisation ",(0,a.jsx)(t,{tex:"W"})," \xe9tant une caract\xe9ristique du m\xe9tal utilis\xe9, la fr\xe9quence seuil ",(0,a.jsx)(t,{tex:"\\nu_0"})," ne d\xe9pend pas de l'intensit\xe9 du rayonnement, conform\xe9ment aux observations exp\xe9rimentales."]}),"\n",(0,a.jsxs)(n.p,{children:["L'effet photo\xe9lectrique et le rayonnement \xe9lectromagn\xe9tique du corps noir montrent que l'\xe9change d'\xe9nergie entre la mati\xe8re et le rayonnement est quantifi\xe9. La constante universelle ",(0,a.jsx)(t,{tex:"h"})," d\xe9couverte par Planck est li\xe9e \xe0 l'existence de ces \xe9changes discontinus d'\xe9nergie."]}),"\n",(0,a.jsx)(n.p,{children:"C'est la mise en \xe9vidence de la nature discontinue des \xe9changes d'\xe9nergie et son interpr\xe9tation qui r\xe9v\xe8le en tant que cons\xe9quence l'aspect corpusculaire de la lumi\xe8re."}),"\n",(0,a.jsx)(n.h2,{id:"quantification-du-spectre-de-lhydrog\xe8ne",children:"Quantification du spectre de l'hydrog\xe8ne"}),"\n",(0,a.jsxs)(n.p,{children:["En 1885, Balmer \xe9tudie le spectre d'\xe9mission de l'atome d'hydrog\xe8ne. Il obtient une s\xe9rie de raies formant un spectre discontinu, et non pas le spectre continu pr\xe9dit par les lois classiques de l'\xe9lectromagn\xe9tisme. Rydberg \xe9tablit en 1900 une loi empirique en ",(0,a.jsx)(t,{tex:"\\dfrac{1}{n^2}"})," (avec ",(0,a.jsx)(t,{tex:"n"})," entier) permettant de retrouver pr\xe9cis\xe9ment les longueurs d'onde d'\xe9mission de cette s\xe9rie de raies. Gr\xe2ce au progr\xe8s des techniques spectroscopiques, Lyman d\xe9couvre en 1906 une autre s\xe9rie de raies dans le domaine ultraviolet, puis Paschen d\xe9tecte une s\xe9rie dans le domaine infrarouge en 1909. On d\xe9nombre en tout 5 s\xe9ries observ\xe9es exp\xe9rimentalement. Elles peuvent \xeatre analys\xe9es par une formule empirique similaire \xe0 celle de Rydberg, \xe9nonc\xe9e par Ritz en 1908 :"]}),"\n",(0,a.jsx)(t,{tex:"\\frac{1}{\\lambda} = R_H \\left(\\frac{1}{n_f^2} - \\frac{1}{n_i^2}\\right)",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["o\xf9 ",(0,a.jsx)(t,{tex:"R_H"})," est la constante de Rydberg, dont la valeur d\xe9termin\xe9e exp\xe9rimentalement vaut ",(0,a.jsx)(t,{tex:"109677{,}30\\ \\text{cm}^{-1}"}),". ",(0,a.jsx)(t,{tex:"n_f"})," et ",(0,a.jsx)(t,{tex:"n_i"})," sont des entiers strictement positifs. Les s\xe9ries observ\xe9es se distinguent par la valeur de ",(0,a.jsx)(t,{tex:"n_f"})," :"]}),"\n",(0,a.jsxs)(n.table,{children:[(0,a.jsx)(n.thead,{children:(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.th,{children:"S\xe9rie"}),(0,a.jsx)(n.th,{children:(0,a.jsx)(t,{tex:"n_f"})}),(0,a.jsx)(n.th,{children:"R\xe9gion d'\xe9mission"})]})}),(0,a.jsxs)(n.tbody,{children:[(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Lyman (1906)"}),(0,a.jsx)(n.td,{children:"1"}),(0,a.jsx)(n.td,{children:"Ultraviolet"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Balmer (1885)"}),(0,a.jsx)(n.td,{children:"2"}),(0,a.jsx)(n.td,{children:"Visible et proche UV"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Paschen (1909)"}),(0,a.jsx)(n.td,{children:"3"}),(0,a.jsx)(n.td,{children:"Infrarouge"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Bracket (1922)"}),(0,a.jsx)(n.td,{children:"4"}),(0,a.jsx)(n.td,{children:"Infrarouge"})]}),(0,a.jsxs)(n.tr,{children:[(0,a.jsx)(n.td,{children:"Pfund (1924)"}),(0,a.jsx)(n.td,{children:"5"}),(0,a.jsx)(n.td,{children:"Infrarouge"})]})]})]}),"\n",(0,a.jsx)(n.p,{children:"Pour tenter de concilier un mod\xe8le atomique plan\xe9taire pour l'atome d'hydrog\xe8ne et la quantification observ\xe9e sur son spectre d'\xe9mission, Bohr publie en 1913 un article intitul\xe9 \"De la constitution des atomes et des mol\xe9cules\" dans lequel il s'appuie sur les travaux de Planck et propose les postulats suivants :"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"L'\xe9lectron circule \xe0 vitesse et \xe9nergie constantes sur des orbites circulaires particuli\xe8res pour lesquelles il y a exacte compensation entre l'attraction coulombienne du noyau et la force centrifuge."}),"\n",(0,a.jsxs)(n.li,{children:["Ces orbites particuli\xe8res se limitent \xe0 celles pour lesquelles le moment cin\xe9tique est un multiple entier de la constante de Planck ",(0,a.jsx)(t,{tex:"h"}),", divis\xe9e par ",(0,a.jsx)(t,{tex:"2\\pi"}),"."]}),"\n",(0,a.jsx)(n.li,{children:"Le changement d'orbite se produit par absorption ou \xe9mission d'un photon. L'\xe9nergie du photon absorb\xe9 ou \xe9mis correspond \xe0 la diff\xe9rence d'\xe9nergie des deux orbites."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"De la condition de quantification du moment cin\xe9tique (postulat 2) r\xe9sulte la quantification des niveaux d'\xe9nergie de l'atome :"}),"\n",(0,a.jsx)(t,{tex:"E_n = -\\frac{me^4}{(4\\pi\\epsilon_0\\hbar)^2} \\frac{Z^2}{2n^2}",display:!0}),"\n",(0,a.jsx)(n.p,{children:"ou encore :"}),"\n",(0,a.jsx)(t,{tex:"E_n = -13{,}6 \\cdot \\frac{Z^2}{n^2}",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["Le nombre entier ",(0,a.jsx)(t,{tex:"n"})," est appel\xe9 nombre quantique principal. Le troisi\xe8me postulat lie la diff\xe9rence d'\xe9nergie entre deux orbites stables \xe0 la fr\xe9quence ",(0,a.jsx)(t,{tex:"\\nu"})," du photon \xe9mis ou absorb\xe9 :"]}),"\n",(0,a.jsx)(t,{tex:"|E_f - E_i| = h\\nu",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["Les travaux de Bohr furent une avanc\xe9e consid\xe9rable dans l'\xe9tablissement de la th\xe9orie quantique, bien qu'ils ne pr\xe9sentent qu'une juxtaposition d'une condition de quantification sur un mod\xe8le classique. En sugg\xe9rant de distinguer, dans la notion de grandeur physique, le concept et les valeurs permises, il ouvrait la voie \xe0 une th\xe9orie formellement plus aboutie qui allait appara\xeetre plus tard avec les travaux de Heisenberg et Schr\xf6dinger. Le mod\xe8le de Bohr fut ensuite raffin\xe9 afin d'expliquer la d\xe9composition hyperfine des raies du spectre de l'hydrog\xe8ne. En effet, l'observation \xe0 r\xe9solution \xe9lev\xe9e montre que les raies ne sont pas uniques mais sont en r\xe9alit\xe9 des groupes de raies distinctes, bien que tr\xe8s rapproch\xe9es. En accord avec la loi d'attraction \xe9lectromagn\xe9tique, Sommerfeld explique le ph\xe9nom\xe8ne en postulant que les \xe9lectrons gravitent sur des orbites non pas circulaires mais elliptiques. Il introduit ainsi deux nombres quantiques suppl\xe9mentaires ",(0,a.jsx)(t,{tex:"l"})," et ",(0,a.jsx)(t,{tex:"m"}),", nomm\xe9s respectivement nombre quantique azimutal et magn\xe9tique. Appara\xeet alors le concept de couche et de sous-couche. En 1921, Stern et Gerlach mettent exp\xe9rimentalement en \xe9vidence le moment magn\xe9tique de l'\xe9lectron. Dans cette exp\xe9rience, un faisceau d'atomes d'argent passant dans un champ magn\xe9tique inhomog\xe8ne se voyait d\xe9vi\xe9 en deux faisceaux. Uhlenbeck et Goudsmit en rendent compte en 1925 en introduisant un quatri\xe8me (et dernier) nombre quantique : le spin de l'\xe9lectron."]}),"\n",(0,a.jsx)(n.h2,{id:"aspect-ondulatoire-de-la-mati\xe8re",children:"Aspect ondulatoire de la mati\xe8re"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"L'hypoth\xe8se de de Broglie."})," En 1923, de Broglie tente de concilier les aspects corpusculaires et ondulatoires de la lumi\xe8re, et propose d'associer \xe0 un photon, de nature corpusculaire, une onde qui d\xe9termine son mouvement probable. Il \xe9tablit \xe9galement la relation liant la quantit\xe9 de mouvement ",(0,a.jsx)(t,{tex:"p"})," du corpuscule \xe0 la longueur de l'onde associ\xe9e (",(0,a.jsx)(t,{tex:"\\lambda"}),") :"]}),"\n",(0,a.jsx)(t,{tex:"\\lambda = \\frac{h}{p} = \\frac{h}{mv}",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["L'ann\xe9e suivante, de Broglie va plus loin et propose de g\xe9n\xe9raliser aux particules mat\xe9rielles le concept d'onde associ\xe9e. Cette hypoth\xe8se, \xe0 premi\xe8re vue fantaisiste, est v\xe9rifi\xe9e exp\xe9rimentalement en 1927 par Davisson et Germer qui mettent en \xe9vidence l'existence du ph\xe9nom\xe8ne de diffraction \xe9lectronique. Si on bombarde un cristal de nickel avec un faisceau d'\xe9lectrons, le diagramme de diffraction obtenu est de la m\xeame forme que celui obtenu en utilisant des rayons ",(0,a.jsx)(t,{tex:"X"}),". Cette observation prouve de mani\xe8re incontestable que la mati\xe8re peut \xeatre associ\xe9e \xe0 un ph\xe9nom\xe8ne ondulatoire."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Interf\xe9rences \xe9lectroniques."})," Avec la diffraction, c'est l'existence des figures d'interf\xe9rences qui prouve le plus s\xfbrement la nature ondulatoire d'un ph\xe9nom\xe8ne. Consid\xe9rons l'exp\xe9rience suivante (r\xe9alis\xe9e en 1961) : si on remplace dans l'exp\xe9rience des fentes de Young la source lumineuse par une source d'\xe9lectrons capable d'\xe9mettre les \xe9lectrons un par un, et l'\xe9cran par un d\xe9tecteur adapt\xe9, on constate, en mesurant le nombre d'impacts sur la cible, que chaque \xe9lectron pris individuellement semble se comporter de mani\xe8re apparemment al\xe9atoire, son impact pouvant se trouver apparemment n'importe o\xf9 sur la cible. Mais au bout d'un temps suffisant, quand un grand nombre d'\xe9lectrons sont arriv\xe9s sur la cible, la courbe du nombre total d'impacts en fonction de la position sur la cible est du m\xeame type que celle obtenue avec une source lumineuse : on observe en effet des zones sans impacts alternant avec des zones o\xf9 le nombre d'impacts est grand. Comme pour les ondes lumineuses, si on ferme une des fentes, l'alternance dispara\xeet. Il y a donc l\xe0 manifestation d'un ph\xe9nom\xe8ne d'interf\xe9rences, bien qu'\xe0 un instant donn\xe9 un seul \xe9lectron se trouve entre les fentes et la cible, et ne peut donc pas interf\xe9rer avec les autres \xe9lectrons. L'aspect ondulatoire se manifeste en fait sur la courbe :"]}),"\n",(0,a.jsx)(t,{tex:"\\text{nombre d'\xe9lectrons d\xe9tect\xe9s} = f(x)",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["o\xf9 ",(0,a.jsx)(t,{tex:"x"})," symbolise une variable de position sur la cible. Cette courbe donne la statistique des impacts, et est proportionnelle \xe0 la probabilit\xe9 statistique de pr\xe9sence (d'impact) des \xe9lectrons en un point du d\xe9tecteur."]}),"\n",(0,a.jsx)(n.p,{children:"En outre, dans cette exp\xe9rience, du fait de la proc\xe9dure employ\xe9e, les \xe9lectrons n'ont pas la possibilit\xe9 d'interagir entre eux. On ne peut alors interpr\xe9ter la propri\xe9t\xe9 d'interf\xe9rence par une interaction entre particules. La propri\xe9t\xe9 ondulatoire est donc un ph\xe9nom\xe8ne probabiliste propre \xe0 chacun des \xe9lectrons."}),"\n",(0,a.jsxs)(n.p,{children:["C'est donc sur la probabilit\xe9 de pr\xe9sence des \xe9lectrons que se manifeste le caract\xe8re ondulatoire de la mati\xe8re. On retiendra aussi que l'aspect ondulatoire de la mati\xe8re ne se manifeste que si la longueur d'onde est appr\xe9ciable en comparaison de la taille de la particule ou de celle du milieu o\xf9 elle \xe9volue. Ici la taille des fentes : si les fentes sont grandes par rapport \xe0 ",(0,a.jsx)(t,{tex:"\\lambda"}),", l'effet d'interf\xe9rence dispara\xeet."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Le principe d'incertitude de Heisenberg."})," Un aspect r\xe9volutionnaire de la th\xe9orie quantique est li\xe9 \xe0 l'ind\xe9termination sur la trajectoire des particules. Le caract\xe8re probabiliste du comportement des particules, tel que montr\xe9 dans l'exp\xe9rience des fentes de Young, s'exprime aussi au travers du principe d'ind\xe9termination (ou d'incertitude) de Heisenberg qui nous enseigne notre incapacit\xe9 \xe0 voir la mati\xe8re \xe0 l'\xe9chelle atomique comme on le ferait \xe0 notre \xe9chelle. Il n'est plus possible de pr\xe9dire la trajectoire d'une particule individuelle. Le concept m\xeame de trajectoire n'est plus valable \xe0 l'\xe9chelle des particules \xe9l\xe9mentaires. L'interpr\xe9tation de Heisenberg se base sur le postulat d'existence d'une action minimale non nulle (produit position ",(0,a.jsx)(t,{tex:"\\times"})," quantit\xe9 de mouvement) lors de la mesure des caract\xe9ristiques d'une trajectoire : position et quantit\xe9 de mouvement. La mesure simultan\xe9e de la position et de la quantit\xe9 de mouvement est alors entach\xe9e d'une incertitude intrins\xe8que li\xe9e au fait qu'elle perturbe la particule. Ainsi, mesurer pr\xe9cis\xe9ment la position d'une particule implique l'utilisation d'un choc avec un photon dont la longueur d'onde correspond \xe0 l'incertitude ",(0,a.jsx)(t,{tex:"\\Delta x"})," voulue sur la position. Mais le choc \xe9lastique entre le photon et la particule (effet Compton) conduit \xe0 une modification de la quantit\xe9 de mouvement de la particule. On ne peut donc pas d\xe9terminer simultan\xe9ment avec une pr\xe9cision voulue ces deux grandeurs : elles sont incompatibles. Soit ",(0,a.jsx)(t,{tex:"\\Delta x"})," l'incertitude sur la position d'une particule et ",(0,a.jsx)(t,{tex:"\\Delta p"})," l'incertitude sur sa quantit\xe9 de mouvement. Le principe de Heisenberg est donn\xe9 par l'in\xe9galit\xe9 :"]}),"\n",(0,a.jsx)(t,{tex:"\\Delta x \\cdot \\Delta p \\geq \\frac{\\hbar}{2}",display:!0}),"\n",(0,a.jsx)(n.p,{children:"qui relie les deux incertitudes. Cette in\xe9galit\xe9 donne donc une limite \xe0 nos capacit\xe9s d'observation, intrins\xe8que \xe0 la nature quantique des particules. Ceci conduit \xe0 l'abandon n\xe9cessaire du concept de trajectoire puisqu'elle n'est plus mesurable, et \xe0 une formulation math\xe9matique enti\xe8rement nouvelle de la physique \xe0 cette \xe9chelle."}),"\n",(0,a.jsxs)(n.p,{children:["On rappelle l'ind\xe9termination d'Heisenberg : ",(0,a.jsx)(t,{tex:"\\Delta A \\Delta B \\geq \\frac{1}{2}|[\\mathbf{A}, \\mathbf{B}]|"}),", ainsi"]}),"\n",(0,a.jsx)(t,{tex:"\\begin{cases} \\text{sur position } \\mathbf{r}_j = r_j \\\\ \\text{sur impulsion } \\mathbf{p}_j = -i\\dfrac{\\hbar\\partial}{\\partial r_j} \\end{cases}",display:!0}),"\n",(0,a.jsx)(n.p,{children:"ainsi"}),"\n",(0,a.jsx)(t,{tex:"[\\mathbf{r}_j, \\mathbf{p}_j] = (\\mathbf{rp} - \\mathbf{pr})\\Psi = r \\times \\Big((-i)\\hbar\\frac{\\partial}{\\partial r}\\Big)\\Psi + i\\hbar\\frac{\\partial}{\\partial r} \\times (r\\Psi) = -ir\\hbar\\frac{\\partial}{\\partial r}(\\Psi) + i\\hbar r\\frac{\\partial\\Psi}{\\partial r} + i\\hbar\\Psi = (i\\hbar)\\Psi",display:!0}),"\n",(0,a.jsxs)(n.p,{children:["donc ",(0,a.jsx)(t,{tex:"\\Delta r \\Delta p \\geq \\frac{1}{2}|i\\hbar| = \\frac{1}{2}\\sqrt{(i\\hbar) \\times (-i\\hbar)} = \\dfrac{\\hbar}{2}"}),"."]})]})}function m(e={}){const{wrapper:n}={...(0,l.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(p,{...e})}):p(e)}},28453(e,n,t){t.d(n,{R:()=>a,x:()=>l});var i=t(96540);const s={},r=i.createContext(s);function a(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);